results<-lapply(cases,function(case)rate_subject_batch(list(case$request),case$registry,'batch','2024-01-06')$value$rows[[1]])
for(i in seq_along(cases)) {
 stopifnot(identical(results[[i]]$status,cases[[i]]$expected$status),identical(results[[i]]$error_code,cases[[i]]$expected$error_code))
 if(results[[i]]$status=='OK') {
  replay<-replay_assessment_history(list(cases[[i]]$request),cases[[i]]$registry,list(results[[i]]),'2024-01-06')$value
  stopifnot(identical(replay$status,'REPRODUCED'))
 }
}
first<-results[[1]]
stopifnot(identical(first$result_hash,cases[[1]]$expected$result_hash),first$value$assessment$state=='FINAL',first$value$assessment$components[[1]]$value==20,first$value$assessment$components[[2]]$value==.5,length(first$value$event_state$processed)==2L)
stopifnot(identical(vapply(first$value$event_trace,function(e)e$status,character(1)),c('APPLIED','DUPLICATE','APPLIED')))
simulation<-Filter(function(r)r$status=='OK'&&any(vapply(r$value$steps,function(s)s$method_id=='simulation.simulate_transactions',logical(1))),results)[[1]]
stopifnot(simulation$value$assessment$components[[1]]$value==20,simulation$value$steps[[1]]$value$transactions[[1]]$risk$pd==1,simulation$value$steps[[1]]$value$transactions[[1]]$risk$conditional_mean_lgd==.2)
policy<-Filter(function(r)r$status=='OK'&&!is.null(r$value$decision),results)[[1]]
stopifnot(policy$value$decision$action=='DECLINE',policy$value$assessment$components[[2]]$value==.5)
policy_case<-Filter(function(x)x$expected$status=='OK'&&!is.null(x$request$recipe$parameters$decision),cases)[[1]]
for(mutation in c('unknown_keyword','missing_keyword','scalar_arguments','scalar_risk')){
 request<-policy_case$request;decision_args<-request$recipe$parameters$decision
 if(mutation=='unknown_keyword'){decision_args$compiled_policy<-decision_args$policy;decision_args$policy<-NULL}
